/* Washer: switch-based hierarchical state machine generated by MachinaState (C99). Do not edit by hand. */
#include "Washer.h"

/* Internal functions */
static size_t RegionOf(Appliances_Washer_State state);
static size_t FirstRegionOf(Appliances_Washer_State state);
static size_t RegionsOf(Appliances_Washer_State state);
static bool IsFinalState(Appliances_Washer_State state);
static void Trace(Appliances_Washer* m, Appliances_Washer_TraceKind kind, const char* name);
static void StartTimers(Appliances_Washer* m, Appliances_Washer_State state);
static void CancelTimers(Appliances_Washer* m, Appliances_Washer_State state);
static int TimerIndex(Appliances_Washer_Event event);
static void OnEntry(Appliances_Washer* m, Appliances_Washer_State state);
static void OnExit(Appliances_Washer* m, Appliances_Washer_State state);
static Appliances_Washer_State Innermost(const Appliances_Washer* m, Appliances_Washer_State state);
static bool AllRegionsFinal(const Appliances_Washer* m, Appliances_Washer_State state);
static void MarkCompletion(Appliances_Washer* m, Appliances_Washer_State state);
static void ExitState(Appliances_Washer* m, Appliances_Washer_State state);
static void EnterState(Appliances_Washer* m, Appliances_Washer_State state);
static void EnterRegion(Appliances_Washer* m, size_t region);
static void EnterDefault(Appliances_Washer* m, Appliances_Washer_State state);
static void EnterDown(Appliances_Washer* m, Appliances_Washer_State from, Appliances_Washer_State target);
static bool HandleEvent(Appliances_Washer* m, Appliances_Washer_State state, Appliances_Washer_Event event);
static void RunCompletions(Appliances_Washer* m);
static bool DispatchState(Appliances_Washer* m, Appliances_Washer_State state, Appliances_Washer_Event event);
static bool DispatchCore(Appliances_Washer* m, Appliances_Washer_Event event);

static size_t RegionOf(Appliances_Washer_State state) {
    switch (state) {
        case Appliances_Washer_State_Washing:
        case Appliances_Washer_State_Rinsing:
        case Appliances_Washer_State_Spinning:
        case Appliances_Washer_State_ProgramDone:
            return 1;
        case Appliances_Washer_State_Heating:
        case Appliances_Washer_State_Holding:
        case Appliances_Washer_State_HeaterDone:
            return 2;
        default:
            return 0;
    }
}

static size_t FirstRegionOf(Appliances_Washer_State state) {
    switch (state) {
        case Appliances_Washer_State_Running:
            return 1;
        default:
            return 0;
    }
}

static size_t RegionsOf(Appliances_Washer_State state) {
    switch (state) {
        case Appliances_Washer_State_Running:
            return 2;
        default:
            return 0;
    }
}

static bool IsFinalState(Appliances_Washer_State state) {
    switch (state) {
        case Appliances_Washer_State_ProgramDone:
        case Appliances_Washer_State_HeaterDone:
            return true;
        default:
            return false;
    }
}

Appliances_Washer_State Appliances_Washer_ParentOf(Appliances_Washer_State state) {
    switch (state) {
        case Appliances_Washer_State_Washing:
        case Appliances_Washer_State_Rinsing:
        case Appliances_Washer_State_Spinning:
        case Appliances_Washer_State_ProgramDone:
        case Appliances_Washer_State_Heating:
        case Appliances_Washer_State_Holding:
        case Appliances_Washer_State_HeaterDone:
            return Appliances_Washer_State_Running;
        default:
            return Appliances_Washer_State_None;
    }
}

const char* Appliances_Washer_StateName(Appliances_Washer_State state) {
    switch (state) {
        case Appliances_Washer_State_Idle:
            return "Idle";
        case Appliances_Washer_State_Running:
            return "Running";
        case Appliances_Washer_State_Washing:
            return "Washing";
        case Appliances_Washer_State_Rinsing:
            return "Rinsing";
        case Appliances_Washer_State_Spinning:
            return "Spinning";
        case Appliances_Washer_State_ProgramDone:
            return "ProgramDone";
        case Appliances_Washer_State_Heating:
            return "Heating";
        case Appliances_Washer_State_Holding:
            return "Holding";
        case Appliances_Washer_State_HeaterDone:
            return "HeaterDone";
        case Appliances_Washer_State_Error:
            return "Error";
        default:
            return "None";
    }
}

const char* Appliances_Washer_EventName(Appliances_Washer_Event event) {
    switch (event) {
        case Appliances_Washer_Event_Start:
            return "Start";
        case Appliances_Washer_Event_Spun:
            return "Spun";
        case Appliances_Washer_Event_TempReached:
            return "TempReached";
        case Appliances_Washer_Event_TempDropped:
            return "TempDropped";
        case Appliances_Washer_Event_SetTemp:
            return "SetTemp";
        case Appliances_Washer_Event_Overheat:
            return "Overheat";
        case Appliances_Washer_Event_Cancel:
            return "Cancel";
        case Appliances_Washer_Event_Reset:
            return "Reset";
        case Appliances_Washer_Event_QuickRinse:
            return "QuickRinse";
        case Appliances_Washer_Event_Washing_After30000ms:
            return "Washing_After30000ms";
        case Appliances_Washer_Event_Rinsing_After20000ms:
            return "Rinsing_After20000ms";
        case Appliances_Washer_Event_Completion:
            return "Completion";
        default:
            return "";
    }
}

static void Trace(Appliances_Washer* m, Appliances_Washer_TraceKind kind, const char* name) {
    if (m->hooks->Trace != NULL) {
        m->hooks->Trace(m->context, kind, name);
    }
}

static void StartTimers(Appliances_Washer* m, Appliances_Washer_State state) {
    switch (state) {
        case Appliances_Washer_State_Washing:
            ++m->timerGeneration[0];
            m->timerArmed[0] = true;
            m->hooks->StartTimer(m->context, Appliances_Washer_Event_Washing_After30000ms, 30000u, m->timerGeneration[0]);
            break;
        case Appliances_Washer_State_Rinsing:
            ++m->timerGeneration[1];
            m->timerArmed[1] = true;
            m->hooks->StartTimer(m->context, Appliances_Washer_Event_Rinsing_After20000ms, 20000u, m->timerGeneration[1]);
            break;
        default:
            break;
    }
}

static void CancelTimers(Appliances_Washer* m, Appliances_Washer_State state) {
    switch (state) {
        case Appliances_Washer_State_Washing:
            m->timerArmed[0] = false;
            m->hooks->CancelTimer(m->context, Appliances_Washer_Event_Washing_After30000ms);
            break;
        case Appliances_Washer_State_Rinsing:
            m->timerArmed[1] = false;
            m->hooks->CancelTimer(m->context, Appliances_Washer_Event_Rinsing_After20000ms);
            break;
        default:
            break;
    }
}

static int TimerIndex(Appliances_Washer_Event event) {
    switch (event) {
        case Appliances_Washer_Event_Washing_After30000ms:
            return 0;
        case Appliances_Washer_Event_Rinsing_After20000ms:
            return 1;
        default:
            return -1;
    }
}

static void OnEntry(Appliances_Washer* m, Appliances_Washer_State state) {
    switch (state) {
        case Appliances_Washer_State_Running:
            m->hooks->lockDoor(m->context);
            break;
        case Appliances_Washer_State_Washing:
            m->hooks->motorSlow(m->context);
            break;
        case Appliances_Washer_State_Spinning:
            m->hooks->motorFast(m->context);
            break;
        case Appliances_Washer_State_Heating:
            m->hooks->heaterOn(m->context);
            break;
        case Appliances_Washer_State_Error:
            m->hooks->alarm(m->context);
            break;
        default:
            break;
    }
}

static void OnExit(Appliances_Washer* m, Appliances_Washer_State state) {
    switch (state) {
        case Appliances_Washer_State_Running:
            m->hooks->unlockDoor(m->context);
            break;
        case Appliances_Washer_State_Spinning:
            m->hooks->motorStop(m->context);
            break;
        case Appliances_Washer_State_Heating:
            m->hooks->heaterOff(m->context);
            break;
        default:
            break;
    }
}

static Appliances_Washer_State Innermost(const Appliances_Washer* m, Appliances_Washer_State state) {
    while (state != Appliances_Washer_State_None && RegionsOf(state) > 0 && m->active[FirstRegionOf(state)] != Appliances_Washer_State_None) {
        state = m->active[FirstRegionOf(state)];
    }
    return state;
}

static bool AllRegionsFinal(const Appliances_Washer* m, Appliances_Washer_State state) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        if (!IsFinalState(m->active[region])) {
            return false;
        }
    }
    return true;
}

static void MarkCompletion(Appliances_Washer* m, Appliances_Washer_State state) {
    switch (state) {
        case Appliances_Washer_State_ProgramDone:
            if (AllRegionsFinal(m, Appliances_Washer_State_Running))
                m->pending[Appliances_Washer_State_Running] = true;
            break;
        case Appliances_Washer_State_HeaterDone:
            if (AllRegionsFinal(m, Appliances_Washer_State_Running))
                m->pending[Appliances_Washer_State_Running] = true;
            break;
        default:
            break;
    }
}

static void ExitState(Appliances_Washer* m, Appliances_Washer_State state) {
    size_t region;
    for (region = FirstRegionOf(state) + RegionsOf(state); region-- > FirstRegionOf(state);) {
        if (m->active[region] != Appliances_Washer_State_None) {
            ExitState(m, m->active[region]);
        }
    }
    Trace(m, Appliances_Washer_Trace_Exit, Appliances_Washer_StateName(state));
    CancelTimers(m, state);
    OnExit(m, state);
    m->active[RegionOf(state)] = Appliances_Washer_State_None;
    m->exited = state;
}

static void EnterState(Appliances_Washer* m, Appliances_Washer_State state) {
    m->active[RegionOf(state)] = state;
    Trace(m, Appliances_Washer_Trace_Enter, Appliances_Washer_StateName(state));
    OnEntry(m, state);
    StartTimers(m, state);
}

static void EnterRegion(Appliances_Washer* m, size_t region) {
    switch (region) {
        case 1:
            EnterDown(m, Appliances_Washer_State_Running, Appliances_Washer_State_Washing);
            break;
        case 2:
            m->hooks->setTemperature(m->context);
            EnterDown(m, Appliances_Washer_State_Running, Appliances_Washer_State_Heating);
            break;
        default:
            break;
    }
}

static void EnterDefault(Appliances_Washer* m, Appliances_Washer_State state) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        EnterRegion(m, region);
    }
    if (RegionsOf(state) == 0) {
        MarkCompletion(m, state);
    }
}

static void EnterDown(Appliances_Washer* m, Appliances_Washer_State from, Appliances_Washer_State target) {
    Appliances_Washer_State state = target;
    Appliances_Washer_State next = Appliances_Washer_State_None;
    size_t region;
    while (Appliances_Washer_ParentOf(state) != from) {
        next = state;
        state = Appliances_Washer_ParentOf(state);
    }
    EnterState(m, state);
    if (next == Appliances_Washer_State_None) {
        EnterDefault(m, state);
        return;
    }
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        if (region == RegionOf(next)) {
            EnterDown(m, state, target);
        } else {
            EnterRegion(m, region);
        }
    }
}

static bool HandleEvent(Appliances_Washer* m, Appliances_Washer_State state, Appliances_Washer_Event event) {
    switch (state) {
        case Appliances_Washer_State_Idle:
            switch (event) {
                case Appliances_Washer_Event_Start:
                    Trace(m, Appliances_Washer_Trace_Transition, "Idle -> Running");
                    ExitState(m, Appliances_Washer_State_Idle);
                    m->hooks->fillWater(m->context);
                    EnterDown(m, Appliances_Washer_State_None, Appliances_Washer_State_Running);
                    return true;
                case Appliances_Washer_Event_QuickRinse:
                    Trace(m, Appliances_Washer_Trace_Transition, "Idle -> Rinsing");
                    ExitState(m, Appliances_Washer_State_Idle);
                    EnterDown(m, Appliances_Washer_State_None, Appliances_Washer_State_Rinsing);
                    return true;
                default:
                    break;
            }
            break;
        case Appliances_Washer_State_Running:
            switch (event) {
                case Appliances_Washer_Event_Cancel:
                    Trace(m, Appliances_Washer_Trace_Transition, "Running -> Idle");
                    ExitState(m, Appliances_Washer_State_Running);
                    m->hooks->drain(m->context);
                    EnterDown(m, Appliances_Washer_State_None, Appliances_Washer_State_Idle);
                    return true;
                case Appliances_Washer_Event_Completion:
                    Trace(m, Appliances_Washer_Trace_Transition, "Running -> Idle");
                    ExitState(m, Appliances_Washer_State_Running);
                    m->hooks->beep(m->context);
                    EnterDown(m, Appliances_Washer_State_None, Appliances_Washer_State_Idle);
                    return true;
                default:
                    break;
            }
            break;
        case Appliances_Washer_State_Washing:
            switch (event) {
                case Appliances_Washer_Event_Washing_After30000ms:
                    Trace(m, Appliances_Washer_Trace_Transition, "Washing -> Rinsing");
                    ExitState(m, Appliances_Washer_State_Washing);
                    m->hooks->drain(m->context);
                    EnterDown(m, Appliances_Washer_State_Running, Appliances_Washer_State_Rinsing);
                    return true;
                default:
                    break;
            }
            break;
        case Appliances_Washer_State_Rinsing:
            switch (event) {
                case Appliances_Washer_Event_Rinsing_After20000ms:
                    Trace(m, Appliances_Washer_Trace_Transition, "Rinsing -> Spinning");
                    ExitState(m, Appliances_Washer_State_Rinsing);
                    EnterDown(m, Appliances_Washer_State_Running, Appliances_Washer_State_Spinning);
                    return true;
                default:
                    break;
            }
            break;
        case Appliances_Washer_State_Spinning:
            switch (event) {
                case Appliances_Washer_Event_Spun:
                    Trace(m, Appliances_Washer_Trace_Transition, "Spinning -> ProgramDone");
                    ExitState(m, Appliances_Washer_State_Spinning);
                    EnterDown(m, Appliances_Washer_State_Running, Appliances_Washer_State_ProgramDone);
                    return true;
                default:
                    break;
            }
            break;
        case Appliances_Washer_State_Heating:
            switch (event) {
                case Appliances_Washer_Event_TempReached:
                    Trace(m, Appliances_Washer_Trace_Transition, "Heating -> Holding");
                    ExitState(m, Appliances_Washer_State_Heating);
                    EnterDown(m, Appliances_Washer_State_Running, Appliances_Washer_State_Holding);
                    return true;
                case Appliances_Washer_Event_Overheat:
                    Trace(m, Appliances_Washer_Trace_Transition, "Heating -> Error");
                    ExitState(m, Appliances_Washer_State_Running);
                    EnterDown(m, Appliances_Washer_State_None, Appliances_Washer_State_Error);
                    return true;
                default:
                    break;
            }
            break;
        case Appliances_Washer_State_Holding:
            switch (event) {
                case Appliances_Washer_Event_Spun:
                    Trace(m, Appliances_Washer_Trace_Transition, "Holding -> HeaterDone");
                    ExitState(m, Appliances_Washer_State_Holding);
                    EnterDown(m, Appliances_Washer_State_Running, Appliances_Washer_State_HeaterDone);
                    return true;
                case Appliances_Washer_Event_TempDropped:
                    Trace(m, Appliances_Washer_Trace_Transition, "Holding -> Heating");
                    ExitState(m, Appliances_Washer_State_Holding);
                    EnterDown(m, Appliances_Washer_State_Running, Appliances_Washer_State_Heating);
                    return true;
                case Appliances_Washer_Event_SetTemp:
                    Trace(m, Appliances_Washer_Trace_Transition, "Holding (internal)");
                    m->hooks->adjust(m->context, ((const Appliances_Washer_SetTempArgs*)m->args)->celsius);
                    return true;
                default:
                    break;
            }
            break;
        case Appliances_Washer_State_Error:
            switch (event) {
                case Appliances_Washer_Event_Reset:
                    if (m->hooks->isCool(m->context)) {
                        Trace(m, Appliances_Washer_Trace_Transition, "Error -> Idle");
                        ExitState(m, Appliances_Washer_State_Error);
                        EnterDown(m, Appliances_Washer_State_None, Appliances_Washer_State_Idle);
                        return true;
                    }
                    break;
                default:
                    break;
            }
            break;
        default:
            break;
    }
    return false;
}

static void RunCompletions(Appliances_Washer* m) {
    for (;;) {
        size_t index = 0;
        while (index < Appliances_Washer_StateCount && !m->pending[index]) {
            ++index;
        }
        if (index == Appliances_Washer_StateCount) {
            return;
        }
        m->pending[index] = false;
        if (m->active[RegionOf((Appliances_Washer_State)index)] == (Appliances_Washer_State)index) {
            HandleEvent(m, (Appliances_Washer_State)index, Appliances_Washer_Event_Completion);
        }
    }
}

/* Offers the event to every active region below `state` first, then to `state` itself. */
static bool DispatchState(Appliances_Washer* m, Appliances_Washer_State state, Appliances_Washer_Event event) {
    bool handled = false;
    Appliances_Washer_State s;
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        if (m->active[region] != Appliances_Washer_State_None && DispatchState(m, m->active[region], event)) {
            handled = true;
            /* Stop if the transition exited `state`, even if it entered it again. */
            for (s = state; s != Appliances_Washer_State_None; s = Appliances_Washer_ParentOf(s)) {
                if (s == m->exited) {
                    return true;
                }
            }
        }
    }
    return handled || HandleEvent(m, state, event);
}

static bool DispatchCore(Appliances_Washer* m, Appliances_Washer_Event event) {
    const int timer = TimerIndex(event);
    if (timer >= 0) {
        m->timerArmed[timer] = false;   /* a timer fires once */
    }
    m->exited = Appliances_Washer_State_None;
    Trace(m, Appliances_Washer_Trace_Event, Appliances_Washer_EventName(event));
    if (m->active[0] != Appliances_Washer_State_None && DispatchState(m, m->active[0], event)) {
        RunCompletions(m);
        return true;
    }
    Trace(m, Appliances_Washer_Trace_Ignored, Appliances_Washer_EventName(event));
    return false;
}

void Appliances_Washer_Init(Appliances_Washer* m, const Appliances_Washer_Hooks* hooks, void* context) {
    size_t i;
    m->hooks   = hooks;
    m->context = context;
    for (i = 0; i < Appliances_Washer_RegionCount; ++i) {
        m->active[i] = Appliances_Washer_State_None;
    }
    m->exited = Appliances_Washer_State_None;
    for (i = 0; i < Appliances_Washer_StateCount; ++i) {
        m->pending[i] = false;
    }
    for (i = 0; i < Appliances_Washer_TimerCount; ++i) {
        m->timerGeneration[i] = 0;
        m->timerArmed[i]      = false;
    }
    m->args = NULL;
}

void Appliances_Washer_Start(Appliances_Washer* m) {
    size_t i;
    if (m->timerArmed[0]) {
        m->timerArmed[0] = false;
        ++m->timerGeneration[0];
        m->hooks->CancelTimer(m->context, Appliances_Washer_Event_Washing_After30000ms);
    }
    if (m->timerArmed[1]) {
        m->timerArmed[1] = false;
        ++m->timerGeneration[1];
        m->hooks->CancelTimer(m->context, Appliances_Washer_Event_Rinsing_After20000ms);
    }
    for (i = 0; i < Appliances_Washer_RegionCount; ++i) {
        m->active[i] = Appliances_Washer_State_None;
    }
    for (i = 0; i < Appliances_Washer_StateCount; ++i) {
        m->pending[i] = false;
    }
    Trace(m, Appliances_Washer_Trace_Start, "Washer");
    EnterDown(m, Appliances_Washer_State_None, Appliances_Washer_State_Idle);
    RunCompletions(m);
}

bool Appliances_Washer_Dispatch(Appliances_Washer* m, Appliances_Washer_Event event) {
    bool handled = false;
    if (event != Appliances_Washer_Event_SetTemp && event != Appliances_Washer_Event_Completion) {
        m->args = NULL;
        handled = DispatchCore(m, event);
        m->args = NULL;
    }
    return handled;
}

bool Appliances_Washer_DispatchSetTemp(Appliances_Washer* m, int celsius) {
    bool handled;
    Appliances_Washer_SetTempArgs args;
    args.celsius = celsius;
    m->args = &args;
    handled = DispatchCore(m, Appliances_Washer_Event_SetTemp);
    m->args = NULL;
    return handled;
}

bool Appliances_Washer_DispatchTimeout(Appliances_Washer* m, Appliances_Washer_Event timeout, unsigned generation) {
    bool handled = false;
    const int index = TimerIndex(timeout);
    if (index >= 0 && m->timerArmed[index] && m->timerGeneration[index] == generation) {
        m->args = NULL;
        handled = DispatchCore(m, timeout);
        m->args = NULL;
    }
    return handled;
}

Appliances_Washer_State Appliances_Washer_Current(const Appliances_Washer* m) {
    return Innermost(m, m->active[0]);
}

bool Appliances_Washer_IsIn(const Appliances_Washer* m, Appliances_Washer_State state) {
    return state != Appliances_Washer_State_None && m->active[RegionOf(state)] == state;
}

bool Appliances_Washer_IsFinished(const Appliances_Washer* m) {
    return ((void)m, false);
}

